package com.rulecraft.decisionops.decisionapi;
import com.rulecraft.decisionops.audit.AuditService;import com.rulecraft.decisionops.catalog.CatalogService;import com.rulecraft.decisionops.decisionapi.domain.*;import com.rulecraft.decisionops.decisionapi.persistence.ApiCredentialRepository;import com.rulecraft.decisionops.identity.security.RuleCraftPrincipal;import com.rulecraft.decisionops.platform.web.DomainProblemException;import com.rulecraft.decisionops.projects.ProjectAccessPolicy;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ApiCredentialService {private static final SecureRandom RANDOM=new SecureRandom();private final ApiCredentialRepository credentials;private final ProjectAccessPolicy access;private final CatalogService catalog;private final AuditService audit;private final Clock clock;public ApiCredentialService(ApiCredentialRepository credentials,ProjectAccessPolicy access,CatalogService catalog,AuditService audit,Clock clock){this.credentials=credentials;this.access=access;this.catalog=catalog;this.audit=audit;this.clock=clock;}@Transactional(readOnly=true)public List<CredentialView> list(RuleCraftPrincipal actor,UUID projectId,UUID serviceId){access.requirePromote(actor,projectId);catalog.getService(actor,projectId,serviceId);return credentials.findTop100ByTenantIdAndProjectIdAndServiceIdOrderByCreatedAtDesc(actor.tenantId(),projectId,serviceId).stream().map(this::view).toList();}@Transactional public CreatedCredential create(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,CreateCredential command){access.requirePromote(actor,projectId);catalog.getService(actor,projectId,serviceId);var label=command==null||command.label()==null?"":command.label().strip();if(label.isBlank()||label.length()>160)bad("RC-API-KEY-LABEL","API key labels contain 1–160 characters.");if(credentials.countByTenantIdAndServiceIdAndStatus(actor.tenantId(),serviceId,ApiCredentialStatus.ACTIVE)>=20)bad("RC-API-KEY-LIMIT","A decision service can have at most 20 active API keys.");var bytes=new byte[32];RANDOM.nextBytes(bytes);var secret="rc_live_"+Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);var prefix=secret.substring(0,16);var value=credentials.saveAndFlush(new ApiCredential(actor.tenantId(),projectId,serviceId,label,prefix,hash(secret),actor.userId(),actor.displayName(),Instant.now(clock)));audit.record(actor.tenantId(),actor.userId(),"DECISION_API_KEY_CREATED","API_CREDENTIAL",value.getId(),Map.of("serviceId",serviceId,"prefix",prefix));return new CreatedCredential(view(value),secret);}@Transactional public CredentialView revoke(RuleCraftPrincipal actor,UUID projectId,UUID serviceId,UUID credentialId,RevokeCredential command){access.requirePromote(actor,projectId);catalog.getService(actor,projectId,serviceId);var value=credentials.findByIdAndTenantIdAndProjectIdAndServiceId(credentialId,actor.tenantId(),projectId,serviceId).orElseThrow(()->new DomainProblemException(HttpStatus.NOT_FOUND,"RC-API-KEY-NOT-FOUND","API key not found."));if(value.getStatus()==ApiCredentialStatus.REVOKED)return view(value);if(command==null||command.expectedVersion()==null||command.expectedVersion()!=value.getVersion())throw new DomainProblemException(HttpStatus.CONFLICT,"RC-API-KEY-STALE","The API key changed. Refresh before retrying.");value.revoke(actor.userId(),Instant.now(clock));credentials.save(value);audit.record(actor.tenantId(),actor.userId(),"DECISION_API_KEY_REVOKED","API_CREDENTIAL",value.getId(),Map.of("serviceId",serviceId,"prefix",value.getKeyPrefix()));return view(value);}private CredentialView view(ApiCredential value){return new CredentialView(value.getId(),value.getLabel(),value.getKeyPrefix(),value.getStatus(),value.getCreatedByName(),value.getCreatedAt(),value.getRevokedAt(),value.getVersion());}public static String hash(String secret){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(secret.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException impossible){throw new IllegalStateException(impossible);}}private void bad(String code,String detail){throw new DomainProblemException(HttpStatus.BAD_REQUEST,code,detail);}public record CreateCredential(String label){}public record RevokeCredential(Long expectedVersion){}public record CredentialView(UUID id,String label,String keyPrefix,ApiCredentialStatus status,String createdByName,Instant createdAt,Instant revokedAt,long version){}public record CreatedCredential(CredentialView credential,String secret){}
}
